import { NavLink, useNavigate } from 'react-router-dom';
import { useEffect, useMemo, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { useDarkMode } from '../context/DarkModeContext';
import useViewport from '../hooks/useViewport';
import { eventService } from '../services/eventService';

const navItems = [
  { to: '/app/dashboard', label: 'Dashboard', icon: '📊' },
  { to: '/app/events', label: 'Events', icon: '🗓️' },
];

export default function Sidebar({ open, onClose }) {
  const { user, logout } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { dark, theme } = useDarkMode();
  const { isDesktop } = useViewport();
  const showActivityLogs = user?.role === 'organiser' || user?.role === 'admin';
  const [recentEvents, setRecentEvents] = useState([]);
  const [recentLoading, setRecentLoading] = useState(false);

  const handleLogout = () => {
    logout();
    toast.success('Logged out successfully');
    navigate('/login');
  };

  useEffect(() => {
    if (!showActivityLogs) return;

    let alive = true;
    setRecentLoading(true);
    eventService.getAll({ sort: '-createdAt', limit: 8, page: 1 })
      .then(({ data }) => {
        if (!alive) return;
        setRecentEvents(Array.isArray(data?.events) ? data.events : []);
      })
      .catch(() => {
        if (!alive) return;
        setRecentEvents([]);
      })
      .finally(() => {
        if (!alive) return;
        setRecentLoading(false);
      });

    return () => { alive = false; };
  }, [showActivityLogs]);

  const activityItems = useMemo(() => {
    if (!showActivityLogs) return [];

    const scoped = user?.role === 'admin'
      ? recentEvents
      : recentEvents.filter((event) => String(event?.organiser?._id || '') === String(user?.id || ''));

    return scoped.slice(0, 5).map((event) => {
      const createdAt = event?.createdAt ? new Date(event.createdAt) : null;
      const dateLabel = createdAt && !Number.isNaN(createdAt.valueOf())
        ? createdAt.toLocaleDateString(undefined, { month: 'short', day: '2-digit' })
        : '—';

      const status = event?.status || 'draft';
      const badge = status === 'published'
        ? 'PUB'
        : status === 'completed'
          ? 'DONE'
          : status === 'cancelled'
            ? 'CXL'
            : 'NEW';

      const capacity = event?.capacity || 0;
      const registered = Math.min(event?.registeredCount || 0, capacity || 0);

      return {
        id: event?._id || `${event?.title || 'event'}-${dateLabel}`,
        badge,
        title: event?.title || 'Untitled event',
        meta: `${dateLabel} • ${registered}/${capacity}`,
      };
    });
  }, [recentEvents, showActivityLogs, user?.id, user?.role]);

  const linkStyle = ({ isActive }) => ({
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    padding: '10px 16px',
    borderRadius: 8,
    textDecoration: 'none',
    fontWeight: 500,
    fontSize: 15,
    color: isActive ? '#6366f1' : theme.textMuted,
    background: isActive ? (dark ? 'rgba(99,102,241,0.15)' : '#eef2ff') : 'transparent',
    transition: 'all 0.15s',
  });

  return (
    <>
      {open && !isDesktop && <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: theme.overlay, zIndex: 39 }} />}
      <aside style={{
        position: 'fixed',
        top: 0,
        left: 0,
        height: '100vh',
        width: 240,
        background: theme.sidebarBg,
        borderRight: `1px solid ${theme.border}`,
        display: 'flex',
        flexDirection: 'column',
        padding: '24px 16px',
        zIndex: 40,
        transform: isDesktop || open ? 'translateX(0)' : 'translateX(-100%)',
        transition: 'transform 0.25s ease, background 0.3s',
        boxShadow: !isDesktop && open ? '4px 0 20px rgba(0,0,0,0.08)' : 'none',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 32, paddingLeft: 8 }}>
          <span style={{ fontSize: 22 }}>🎪</span>
          <span style={{ fontWeight: 700, fontSize: 18, color: theme.text }}>EventFlow</span>
        </div>

        <nav style={{ display: 'flex', flexDirection: 'column', gap: 4, flex: 1 }}>
          {navItems.map((item) => (
            <NavLink key={item.to} to={item.to} style={linkStyle} onClick={!isDesktop ? onClose : undefined}>
              <span>{item.icon}</span> {item.label}
            </NavLink>
          ))}
        </nav>

        {showActivityLogs && (
          <div style={{
            marginTop: 14,
            padding: 12,
            borderRadius: 12,
            border: `1px solid ${theme.border}`,
            background: theme.surface,
            boxShadow: theme.cardShadow,
            marginBottom: 16,
          }}>
            <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: 10 }}>
              <div style={{ fontWeight: 700, fontSize: 13, color: theme.text }}>Activity Logs</div>
              <div style={{ fontSize: 12, color: theme.textFaint }}>{recentLoading ? 'Loading…' : ''}</div>
            </div>

            {activityItems.length === 0 ? (
              <div style={{ fontSize: 12, color: theme.textMuted, lineHeight: 1.35 }}>
                No recent activity yet.
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, maxHeight: 180, overflow: 'auto', paddingRight: 6 }}>
                {activityItems.map((item) => (
                  <div key={item.id} style={{ display: 'flex', gap: 10, alignItems: 'flex-start' }}>
                    <div style={{
                      width: 34,
                      height: 24,
                      borderRadius: 8,
                      display: 'grid',
                      placeItems: 'center',
                      background: dark ? 'rgba(255,255,255,0.06)' : '#f8fafc',
                      border: `1px solid ${theme.border}`,
                      flex: '0 0 auto',
                      marginTop: 2,
                      fontSize: 11,
                      fontWeight: 800,
                      color: theme.textMuted,
                      letterSpacing: 0.2,
                    }}>
                      {item.badge}
                    </div>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontSize: 12.5, fontWeight: 600, color: theme.text, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }} title={item.title}>
                        {item.title}
                      </div>
                      <div style={{ fontSize: 11.5, color: theme.textFaint, marginTop: 2 }}>{item.meta}</div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {user && (
          <div style={{ borderTop: `1px solid ${theme.border}`, paddingTop: 16 }}>
            <div style={{ fontSize: 13, color: theme.textMuted, marginBottom: 4, textTransform: 'capitalize' }}>{user.role}</div>
            <div style={{ fontWeight: 600, fontSize: 14, color: theme.text, marginBottom: 12 }}>{user.name}</div>
            <div style={{ fontSize: 12, color: theme.textFaint, marginBottom: 12, wordBreak: 'break-word', lineHeight: 1.4 }}>{user.email}</div>
            <button onClick={handleLogout} style={{
              width: '100%', padding: '9px 0', borderRadius: 8, border: `1px solid ${dark ? '#7f1d1d' : '#fee2e2'}`,
              background: dark ? 'rgba(239,68,68,0.1)' : '#fff5f5', color: '#ef4444', fontWeight: 600, fontSize: 14, cursor: 'pointer',
            }}>
              Logout
            </button>
          </div>
        )}
      </aside>
    </>
  );
}
